http-status-code:
@media (max-width: 720px) {
  .detail :is(.dh-demo, .usage-box, .anat-stage, .variant-demo, .scene-shot, .concept-stage) { max-width: 100%; }
  .detail :is(.dh-demo, .usage-box, .anat-stage, .variant-demo, .scene-shot, .concept-stage) :is(img, video, canvas) { max-width: 100%; height: auto; }
  .reference-link { min-width: 0px; flex-wrap: wrap; gap: 4px 16px; }
  .reference-source, .reference-title { min-width: 0px; max-width: 100%; overflow-wrap: anywhere; }
  .usage-box { padding: 18px 16px 20px; }
  .distinction-card { padding: 2px 0px 10px; }
  .anat-stage { padding: 16px 12px; }
  .variant-demo { padding: 14px 10px; }
  .scene-shot .sc-body { padding: 12px; }
  .prompt-box { gap: 10px; padding: 14px; }
  .prompt-box code { min-width: 0px; }
  .prompt-box-dialogue { padding-left: 42px; }
  .prompt-box-dialogue blockquote { min-width: 0px; }
}

@media (max-width: 560px) {
  .concept-stage { margin-inline: -8px; padding: 14px; border-radius: 12px; }
  .scene-controls { justify-content: flex-start; overflow-x: auto; padding-bottom: 4px; }
  .scene-controls button { flex: 0 0 auto; }
  .compare-heading, .usage-receipt { align-items: flex-start; flex-direction: column; }
  .usage-receipt { width: 100%; gap: 6px; }
  .token-source strong { font-size: 17px; }
  .context-request-head { flex-direction: column; }
  .speed-axis span { font-size: 9px; }
  .speed-bars { min-height: 120px; }
  .usage-ledger > button { grid-template-columns: minmax(0px, 1fr); gap: 4px; }
  .step-buttons { justify-content: flex-start; overflow-x: auto; }
  .stage-conclusion { font-size: 13px; text-align: left; }
  .multimodal-heading { align-items: flex-start; flex-direction: column; gap: 7px; margin-bottom: 16px; }
  .modality-panel li { min-height: 68px; padding: 10px; }
  .modality-panel li > i { font-size: 20px; }
}

@media (prefers-reduced-motion: reduce) {
  .concept-stage *, .concept-stage ::after, .concept-stage ::before { scroll-behavior: auto !important; transition-duration: 0.01ms !important; animation: auto ease 0s 1 normal none running none !important; }
}

@media (max-width: 620px) {
  .scope-scene .scope-layout { grid-template-columns: minmax(0px, 1fr); }
  .scope-arrow { justify-self: center; transform: rotate(90deg); }
}

@media (max-width: 620px) {
  .debt-scene .debt-flow { grid-template-columns: minmax(0px, 1fr); }
  .debt-steps { grid-template-columns: repeat(2, minmax(0px, 1fr)); }
}

@media (max-width: 620px) {
  .persona-scene .persona-layout { grid-template-columns: minmax(0px, 1fr); }
  .persona-arrow { justify-self: center; transform: rotate(90deg); }
}

@media (max-width: 560px) {
  .proto-scene .proto-flow { grid-template-columns: minmax(0px, 1fr); }
}

@media (max-width: 620px) {
  .track-scene .track-layout { grid-template-columns: minmax(0px, 1fr); }
  .track-arrow { justify-self: center; transform: rotate(90deg); }
}

@container wf-stage (max-width: 900px) {
  .wf-canonical-evidence { grid-template-columns: minmax(0px, 1fr); }
  .wf-canonical-evidence .wf-flow-arrow { transform: rotate(90deg); justify-self: center; }
}

@container wf-stage (max-width: 820px) {
  .wf-css-evidence, .wf-dom-evidence { grid-template-columns: minmax(0px, 1fr); }
}

@container wf-stage (max-width: 720px) {
  .wf-app-icon-map, .wf-favicon-evidence, .wf-logo-evidence, .wf-manifest-evidence, .wf-metadata-map, .wf-not-found-evidence, .wf-sitemap-evidence, .wf-title-evidence { grid-template-columns: minmax(0px, 1fr); }
  .wf-flow-arrow { transform: rotate(90deg); justify-self: center; }
  .wf-devtools-window, .wf-og-evidence, .wf-robots-evidence { grid-template-columns: minmax(0px, 1fr); }
  .wf-devtools-page { min-height: 0px; border-right: 0px; border-bottom: 1px solid var(--border); }
  .wf-cache-route, .wf-cookie-flow, .wf-hosting-timeline { grid-template-columns: minmax(0px, 1fr); }
  .wf-cache-route > span, .wf-cookie-flow > span, .wf-hosting-timeline > span { transform: rotate(90deg); justify-self: center; }
  .wf-cache-route > div, .wf-cookie-flow > div, .wf-hosting-timeline > div { min-height: 0px; }
}

@media (max-width: 620px) {
  .wf-stage { padding: 16px; }
}

@container wf-stage (max-width: 520px) {
  .wf-stage > .scene-controls { justify-content: flex-start; overflow-x: auto; padding-bottom: 4px; }
  .wf-stage > .scene-controls::-webkit-scrollbar { display: none; }
  .wf-stage > .scene-controls button { flex: 0 0 auto; }
  .wf-network-proof, .wf-site-source { align-items: flex-start; flex-direction: column; }
  .wf-metadata-consumer.consumer-2, .wf-robots-results, .wf-title-results { grid-template-columns: minmax(0px, 1fr); }
  .wf-metadata-consumer.consumer-2 > small { grid-column: auto; }
  .wf-home-grid { grid-template-columns: repeat(4, 38px); gap: 8px; }
  .wf-home-grid :is(i, span) { width: 38px; height: 38px; }
  .wf-logo-context nav { display: none; }
  .wf-logo-context header > i { display: block; }
  .wf-devtools-panel pre { font-size: 13px; }
}

@media (max-width: 560px) {
  .wf-field-map { grid-template-columns: minmax(0px, 1fr); }
  .wf-field-map > span { transform: rotate(90deg); }
  .wf-dtype-demo { grid-template-columns: minmax(0px, 1fr); }
}

@media (max-width: 560px) {
  .wf-io-flow { grid-template-columns: minmax(0px, 1fr); }
  .wf-io-flow > span { display: none; }
  .wf-ph-demo { grid-template-columns: minmax(0px, 1fr); }
}

@media (max-width: 560px) {
